 AS discount_codes, NULL::NUMBER(10,2) AS tax_rate, NULL::VARCHAR AS EAN FROM MAPLEMONK.PHILIPS_SWIGGY_SALES_FACT_ITEMS; create or replace table philips_db.Maplemonk.Final_customerID as with new_phone_numbers as ( select phone, contact_num, 19700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) as contact_num, phone from philips_db.Maplemonk.philips_db_sales_consolidated_intermediate ) a ), int as ( select contact_num, email, coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email, maple_monk_id, 19800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10)) as contact_num, e.email, maple_monk_id from ( select phone as contact_num, email from philips_db.Maplemonk.philips_db_sales_consolidated_intermediate ) e left join new_phone_numbers p on p.contact_num = right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10) ) a ) b ) select contact_num, email, maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table philips_db.Maplemonk.philips_db_sales_consolidated as select coalesce(m.maple_monk_id_phone, d.maple_monk_id) as customer_id_final, min(case when lower(order_status) not in (\'cancelled\') then order_date end) over(partition by customer_id_final) as first_complete_order_date, m.* from ( select c.maple_monk_id as maple_monk_id_phone, o.* from philips_db.Maplemonk.philips_db_sales_consolidated_intermediate o left join ( select * from ( select contact_num phone, maple_monk_id, row_number() over (partition by contact_num order by maple_monk_id asc) magic from philips_db.Maplemonk.Final_customerID ) where magic =1 )c on c.phone = right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'),10) )m left join ( select distinct maple_monk_id, email from philips_db.Maplemonk.Final_customerID where contact_num is null )d on d.email = m.email; ALTER TABLE philips_db.Maplemonk.philips_db_sales_consolidated drop COLUMN new_customer_flag ; ALTER TABLE philips_db.Maplemonk.philips_db_sales_consolidated ADD COLUMN new_customer_flag varchar(50); ALTER TABLE philips_db.Maplemonk.philips_db_sales_consolidated ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE philips_db.Maplemonk.philips_db_sales_consolidated drop COLUMN acquisition_product ; ALTER TABLE philips_db.Maplemonk.philips_db_sales_consolidated ADD COLUMN acquisition_product varchar(16777216); ALTER TABLE philips_db.Maplemonk.philips_db_sales_consolidated ADD COLUMN acquisition_channel varchar(16777216); ALTER TABLE philips_db.Maplemonk.philips_db_sales_consolidated ADD COLUMN acquisition_marketplace varchar(16777216); UPDATE philips_db.Maplemonk.philips_db_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date then \'New\' WHEN Order_Date < first_complete_order_date or first_complete_order_date is null THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date then \'Repeat\' END AS Flag FROM philips_db.Maplemonk.philips_db_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE philips_db.Maplemonk.philips_db_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) in (\'cancelled\') end) THEN \'Yet to make completed order\' ELSE new_customer_flag END; UPDATE philips_db.Maplemonk.philips_db_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Last_day(order_date, \'month\') = Last_day(first_complete_order_date, \'month\') THEN \'New\' WHEN Last_day(order_date, \'month\') < Last_day(first_complete_order_date, \'month\') or acquisition_date is null THEN \'Yet to make completed order\' WHEN Last_day(order_date, \'month\') > Last_day(first_complete_order_date, \'month\') THEN \'Repeat\' END AS Flag FROM philips_db.Maplemonk.philips_db_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE philips_db.Maplemonk.philips_db_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' ELSE new_customer_flag_month END; CREATE OR replace temporary TABLE philips_db.Maplemonk.temp_source_1 AS SELECT DISTINCT customer_id_final, channel, marketplace FROM ( SELECT DISTINCT customer_id_final, order_date, source as channel, shop_name as marketplace, Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM philips_db.Maplemonk.philips_db_sales_consolidated ) res WHERE order_date=firstorderdate; UPDATE philips_db.Maplemonk.philips_db_sales_consolidated AS a SET a.acquisition_channel=b.channel FROM philips_db.Maplemonk.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; UPDATE philips_db.Maplemonk.philips_db_sales_consolidated AS a SET a.acquisition_marketplace=b.marketplace FROM philips_db.Maplemonk.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE philips_db.Maplemonk.temp_product_1 AS SELECT DISTINCT customer_id_final, product_name_final, Row_number() OVER (partition BY customer_id_final ORDER BY SELLING_PRICE DESC) rowid FROM ( SELECT DISTINCT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM philips_db.Maplemonk.philips_db_sales_consolidated )res WHERE order_date=firstorderdate; UPDATE philips_db.Maplemonk.philips_db_sales_consolidated AS A SET A.acquisition_product=B.product_name_final FROM ( SELECT * FROM philips_db.Maplemonk.temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final;",
